SELECT game_id AS "gameId", cost_id AS "costId", ability_id AS "abilityId", phase_id AS "phaseId", resource_key AS "resourceKey", amount_formula_key AS "amountFormulaKey", allow_partial AS "allowPartial", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_costs WHERE game_id = #{gameId}
AND ability_id = #{abilityId}
AND phase_id = #{phaseId}
ORDER BY ability_id, cost_id
